// Parent process before fork()
int fd = open("log.txt", O_RDWR | O_CREAT);

// After fork():
pid_t pid = fork();

if (pid == 0) {
    // Child: fd still refers to the same open file description
    write(fd, "Child data\n", 11);
    close(fd);
} else {
    // Parent: fd is also available
    write(fd, "Parent data\n", 12);
    // Crucial: Must close fd in parent too, or file remains open
    wait(NULL);
    close(fd);
}
